const textStates = new WeakMap();
const attributeStates = new WeakMap();
const attributes = ['placeholder', 'title', 'aria-label'];
const translateText = (value, language) =>
  languageTranslations[language]?.[value] || extendedTranslations[language]?.[value] || value;

function applyTextNode(node, language) {
  const current = node.nodeValue || '';
  const trimmed = current.trim();
  if (!trimmed) return;
  let state = textStates.get(node);
  if (!state || state.lastApplied !== trimmed) state = { source: trimmed, lastApplied: null };
  const translated = translateText(state.source, language);
  if (translated !== state.source) node.nodeValue = current.replace(trimmed, translated);
  else if (trimmed !== state.source) node.nodeValue = current.replace(trimmed, state.source);
  state.lastApplied = translated;
  textStates.set(node, state);
}

function applyAttributes(element, language) {
  let states = attributeStates.get(element);
  if (!states) { states = {}; attributeStates.set(element, states); }
  for (const attribute of attributes) {
    const current = element.getAttribute(attribute);
    if (current == null) continue;
    let state = states[attribute];
    if (!state || state.lastApplied !== current) state = { source: current, lastApplied: null };
    const translated = translateText(state.source, language);
    if (current !== translated) element.setAttribute(attribute, translated);
    state.lastApplied = translated;
    states[attribute] = state;
  }
}

function translateSubtree(node, language) {
  if (node.nodeType === Node.TEXT_NODE) { applyTextNode(node, language); return; }
  if (node.nodeType !== Node.ELEMENT_NODE && node !== document.body) return;
  if (node.nodeType === Node.ELEMENT_NODE) applyAttributes(node, language);
  const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) applyTextNode(walker.currentNode, language);
  node.querySelectorAll?.('[placeholder],[title],[aria-label]').forEach(element => applyAttributes(element, language));
}

export function observeTranslations(root, language) {
  translateSubtree(root, language);
  const observer = new MutationObserver(records => {
    for (const record of records) {
      if (record.type === 'characterData') applyTextNode(record.target, language);
      else if (record.type === 'attributes') applyAttributes(record.target, language);
      else record.addedNodes.forEach(node => translateSubtree(node, language));
    }
  });
  observer.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: attributes });
  return () => observer.disconnect();
}